def ligar_registros_antigos(apps, schema_editor):
    """Registros de antes desta migração: liga ao cliente pelo formato exato de cada descrição
    ("Maria", "Maria · R$ 10,00", "Venda #3 · Maria · R$ 10,00"), nunca por um pedaço solto do nome."""
    Cliente = apps.get_model('infrastructure', 'Cliente')
    RegistroDeAlteracao = apps.get_model('infrastructure', 'RegistroDeAlteracao')
    for cliente in Cliente.objects.exclude(nome='').iterator():
        nome = cliente.nome
        registros = RegistroDeAlteracao.objects.filter(loja_id=cliente.loja_id, acao__in=CITAM_CLIENTE).filter(
            Q(descricao=nome) | Q(descricao__startswith=f"{nome} · ") | Q(descricao__contains=f" · {nome} · ")
        )
        for registro in registros:
            registro.clientes.add(cliente)



